#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string s;
    cin >> s;

    int n = s.size();
    vector<int> p(n, 0);

    // @default
    // @camera auto zoom(1.6)
    // @enddefault

    // 共用版面：上排字串，下排 prefix function
    // @preset kmp_view
    // @object char(s) with labels(value,index)
    // @object p with labels(value,index)
    // @place s.left-bottom at p.left-top offset(0,-90)
    // @endpreset

    // 計算期間的指標與進度
    // @preset kmp_cursor
    // @pointer i at s
    // @pointer j at s
    // @pointer i-1 at p
    // @style p[0:i-1] focus
    // @endpreset

    // @frame use kmp_view
    // @style p[0] focus
    // @text "p[i] 表示字串 s[0~i] 的最長相等真前後綴長度。" at p.bottom

    for (int i = 1; i < n; i++) {
        int j = p[i - 1];

        // @frame use kmp_view,kmp_cursor
        // @arrow from s[i] to p[i-1] color AV_green!
        // @arrow from p[i-1] to s[j].index-label.bottom color AV_green!
        // @style p[i] highlight,point
        // @text "開始計算 p[${i}]：上一段 s[0~${i-1}] 的答案是 p[${i-1}] = ${j}。\n先令 {j = p[i-1]: j 等於 p 的 i-1}，嘗試比較 s[${i}] 與 s[${j}]，看原本的相等前後綴能否延長。" at p.bottom

        while (j > 0 && s[i] != s[j]) {
            j = p[j - 1];

            // @frame use kmp_view,kmp_cursor
            // @let _j = before(j)
            // @style p[_j] highlight,point
            // @arrow from p[_j] to p[_j-1] as "fallback-index" color AV_red!
            // @arrow from p[_j-1] to s[p[_j-1]].index-label.bottom as "fallback-target" color AV_red!
            // @text "失配：s[${i}] = '${s[i]}'，但 s[${_j}] = '${s[_j]}'，長度 ${_j} 的候選無法延長。\n改用這個候選本身的最長相等真前後綴：j = p[${_j-1}] = ${j}。\ni 保持 ${i}，接著用同一個字元比較 s[${j}]，不必重新從頭找。" at p.bottom
        }

        // @frame use kmp_view,kmp_cursor
        // @style p[i] highlight,point
        // @text "現在比較 s[${i}] = '${s[i]}' 與 s[${j}] = '${s[j]}'。\n若相同，候選長度增加 1；若不同，此時 j 已是 0，答案就是 0。" at p.bottom

        if (s[i] == s[j]) {
            j++;

            // @frame use kmp_view,kmp_cursor
            // @style p[i] highlight,point
            // @text "匹配成功：剛才比較的 s[${i}] 與 s[${j-1}] 相同，因此 j 增加為 ${j}。\n現在 s[0~${j-1}] 與 s[${i-j+1}~${i}] 相等，前後綴長度為 ${j}。" at p.bottom
        }

        p[i] = j;

        // @frame use kmp_view,kmp_cursor
        // @style p[0:i] focus
        // @style p[i] highlight,point
        // @arrow from p[j].index-label.top to p[i] color AV_green!
        // @text "將目前的候選長度 j = ${j} 寫入 p[${i}]。\n因此 s[0~${i}] 的最長相等真前後綴長度是 ${p[i]}。" at p.bottom
    }

    // @frame use kmp_view
    // @style p[0:n-1] focus
    // @text "prefix function 建表完成：p[0~${n-1}] 都已計算。\n每個 p[i] 都記錄 s[0~i] 的最長相等真前後綴長度；失配時可利用這些答案快速回退。" at p.bottom

    for (int i = 0; i < n; i++)
        cout << p[i] << (i + 1 == n ? '\n' : ' ');
}

